axiam_error_kind_t axiam_resources_list(axiam_client_t *c, const axiam_mgmt_page_req_t *page, axiam_mgmt_resource_page_t **out, axiam_error_t *err) {
    if (out) *out = NULL;
    char *path = axiam_mgmt_path("/api/v1/resources", NULL, NULL, 0);
    if (!path) {
        axiam_error_set(err, AXIAM_ERR_NETWORK, 0, "resources.list: could not build the request path");
        return AXIAM_ERR_NETWORK;
    }
    const char *q_names[3];
    const char *q_values[3];
    char offset_buf[24], limit_buf[24];
    axiam_mgmt_page_query(page, offset_buf, limit_buf);
    q_names[0] = "offset"; q_values[0] = offset_buf;
    q_names[1] = "limit"; q_values[1] = limit_buf;
    q_names[2] = "search";
    q_values[2] = page ? axiam_mgmt_page_search(page->search) : NULL;
    path = axiam_mgmt_query(path, q_names, q_values, 3);
    if (!path) {
        axiam_error_set(err, AXIAM_ERR_NETWORK, 0, "resources.list: out of memory");
        return AXIAM_ERR_NETWORK;
    }
    char *body_json = NULL;
    cJSON *json = NULL;
    axiam_error_kind_t rc = axiam_mgmt_send(
        c, "resources.list", "GET", "/api/v1/resources", path, body_json,
        &json, err);
    free(path);
    free(body_json);
    if (rc != AXIAM_OK) return rc;
    axiam_mgmt_resource_page_t *result = (axiam_mgmt_resource_page_t *) calloc(1, sizeof(*result));
    if (!result) { cJSON_Delete(json); return AXIAM_ERR_NETWORK; }
    const cJSON *items = axiam_mgmt_page_items(json);
    size_t n = items ? (size_t) cJSON_GetArraySize(items) : 0;
    if (n > 0) {
        result->items = (axiam_mgmt_resource_t **) calloc(n, sizeof(axiam_mgmt_resource_t *));
        if (!result->items) { axiam_mgmt_resource_page_free(result); cJSON_Delete(json); return AXIAM_ERR_NETWORK; }
        for (size_t i = 0; i < n; i++)
            result->items[i] = axiam_mgmt_resource_parse(cJSON_GetArrayItem((cJSON *) items, (int) i));
        result->count = n;
    }
    result->total = axiam_mgmt_page_total(json, (long) n);
    result->request = page ? *page : (axiam_mgmt_page_req_t) { 0, AXIAM_MGMT_DEFAULT_LIMIT, NULL };
    cJSON_Delete(json);
    if (out) *out = result;
    else axiam_mgmt_resource_page_free(result);
    return AXIAM_OK;
}

